<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;"> (param = :mu, coef = &quot;x&quot;, estimate = 0.49949236057252433, lower = 0.43905965187659424, upper = 0.5601510661608071)</span></span>
